# TROCAS DE OBRA: pos 88: de The Velveteen Rabbit para Corduroy
# TROCAS DE OBRA: pos 89: de A Christmas Carol para Pippi Longstocking
# TROCAS DE OBRA: pos 90: de A Christmas Carol para The Price Is Right
# TROCAS DE OBRA: pos 91: mantida The Very Hungry Caterpillar
# TROCAS DE OBRA: pos 92: de The Very Hungry Caterpillar para Green Eggs and Ham
# TROCAS DE OBRA: pos 93: mantida Little Jack Horner
# TROCAS DE OBRA: pos 94: de Little Jack Horner para Blueberries for Sal
import json

HOT_POS = [(14, 16), (40, 14), (66, 14), (88, 16), (50, 84)]
RSK15 = ['rdg', 'pat', 'vplay', 'sbuild', 'build', 'order', 'balloons', 'dictate', 'soundlab', 'scene', 'dquiz', 'scenebuild', 'produce', 'review', 'wrap']


def hot(rows):
    return [dict(e=e, x=x, y=y, en=en, pt=pt, say=say, sayPt=sp) for (e, en, pt, say, sp), (x, y) in zip(rows, HOT_POS)]


def gap(q, pt, opts, a, why):
    return dict(q=q, pt=pt, opts=opts, a=a, why=why)


def trap(opts, a, why, q='Qual frase está certa?'):
    return dict(q=q, opts=opts, a=a, why=why)


def exp(ic, en, tag, pt, use, ex_en, ex_pt):
    return dict(ic=ic, en=en, tag=tag, pt=pt, use=use, ex=[ex_en, ex_pt])


def verb(v, ic, pt, eu, ele, ex_en, ex_pt, note):
    return dict(v=v, ic=ic, pt=pt, f=[['eu', eu], ['ele/ela', ele]], ex=[ex_en, ex_pt], note=note)


def page(label, slots, end='.'):
    return dict(label=label, slots=[dict(cat=c, opts=[list(o) for o in opts]) for c, opts in slots], end=[end, end])


def mission(ic, name, desc, prompt, chips, model, check, kw, tips, ok, reply):
    return dict(ic=ic, name=name, desc=desc, data=dict(prompt=prompt, ph='Escreva a sua resposta aqui…', chips=chips, model=model, check=check, kw=kw, tips=tips, ok=ok, reply=reply))


def rnd(say, opts, a, why):
    return dict(fig='🎧', say=say, ask='Qual palavra você ouviu?', opts=opts, a=a, why=why)


def hw(say, opts, a, why):
    return dict(fig='🎧', say=say, ask='Ouça e toque na palavra.', opts=opts, a=a, why=why)


def hp(say, emojis, a, why):
    return dict(fig='🎧', say=say, ask='Ouça e toque na figura.', opts=[[e, ''] for e in emojis], a=a, why=why, pic=1)


def fm(from_, to, say, note):
    return dict(from_=from_, to=to, say=say, note=note)


def use(ico, tag, en, pt):
    return dict(ico=ico, tag=tag, en=en, pt=pt)


def rl(tag, c, text, ex):
    return dict(tag=tag, c=c, text=text, ex=ex)


def mk(n, title, sub, label, why, vocab, cover, cover_sub, cover_say, recap, teaser, cast, lines, quiz, rdg, dictate, produce,
       scenes, sc, names, stage, obra, gancho, hotrows, gaps, traps, sticker, rule, mission_ic,
       exps, exp_scene, lab, hunt, vb, mold, speak, mtrap, mgap, expq, missions, cx):
    rs = {k: scenes[i % len(scenes)] for i, k in enumerate(RSK15)}
    B = dict(title=title, sub=sub, pattern_label=label, why=why,
             vocab=[[w, pt, snd] for (w, pt, snd, em) in vocab], balloons=[[em, w.lower()] for (w, pt, snd, em) in vocab],
             cover_art=dict(s=cover[0], items=[[e, x, y, s, 'bob'] for (e, x, y, s) in cover[1]], seed=cover[2]),
             cover_sub=cover_sub, cover_say=cover_say, wrap_recap=recap, teaser=dict(t=teaser[0], d=teaser[1]),
             cast={k: [v[0], v[1]] for k, v in cast.items()}, lines=lines,
             quiz=[dict(q=q, pt=pt, opts=[list(o) for o in opts], a=a, line=ln, why=why_) for (q, pt, opts, a, ln, why_) in quiz],
             rdg_q=dict(q=rdg[0], o=rdg[1], a=rdg[2], why=rdg[3]), dictate=dictate, produce=produce, rs=rs, sc=sc)
    cov = B['cover_art']
    X = dict(n=n, review=True, names=names, stage=dict(rs=stage[0], chars=stage[1]), obra=obra, gancho=gancho, hot=hot(hotrows),
             gap=gaps, trap=traps, sticker=dict(title=sticker[0], sub=sticker[1], rs=sticker[2], chars=sticker[3]),
             speakers={k: v[2] for k, v in cast.items()}, rule=rule, mission_ic=mission_ic)
    XT = dict(exp=exps, exp_scene=dict(rs=exp_scene[0], lines=exp_scene[1]), lab=lab, hunt=hunt)
    VB = dict(title=vb[0], tip=vb[1], items=vb[2])
    MR = dict(mold=mold, speak=speak, trap=mtrap, gap=mgap, expq=expq, missions=missions)
    return json.loads(json.dumps(dict(B=B, X=X, XT=XT, VB=VB, MR=MR, CX=cx)))


def prod(prompt, ph, chips, model, check, kw, tips, ok, reply):
    return dict(prompt=prompt, ph=ph, chips=chips, model=model, check=check, kw=kw, tips=tips, ok=ok, reply=reply)


def cxs(rows):
    return [dict(text=t, pt=p, opts=o, a=0) for (t, p, o) in rows]


EPS = []


def lab(short, title, say, what, how, pt, ex, pairs, tip, phrase, rounds):
    return dict(short=short, title=title, say=say, intro=dict(what=what, how=how, pt=pt), ex=ex, pairs=pairs, tip=tip, phrase=phrase, rounds=rounds)


